{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.fablestreet_historical_website_sales_intermediate as SELECT \'WEBSITE\' as marketplace, cast(PARSE_DATE(\'%b %e %Y\',CONCAT(SUBSTR(Month, 1, 3), \' \',Date, \' \',Year)) as date) AS order_date, UPPER(skucode) AS SKUCode, UPPER(category) AS Category, currency, item_sku AS product_id, item_name AS product_name, dress_code, UPPER(billing_zip) AS billing_zip, TRIM(billing_city) AS billing_city, TRIM(shipping_city) AS shipping_city, TRIM(item_status) AS item_status, itemoptions, Billing_Name, TRIM(order_number) AS order_number, Order_Source AS source, TRIM(UPPER(Order_Status)) AS Order_Status, shipping_zip AS delivery_pincode, Billing_State, TRIM(shipping_phone_number) AS shipping_contact, TRIM(billing_phone_number) AS billing_contact, Invoice_Increment_ID, UPPER(order_shipping_method) AS courier, shipping_country, TRIM(Customer_Email) AS Email, TRIM(Shipping_State_Name) AS state, UPPER(Order_Payment_Method) AS payment_method, CASE WHEN REGEXP_CONTAINS(invoice_date, r\'[a-zA-Z]{3} [0-9]{1,2}, [0-9]{4}\') THEN PARSE_DATETIME(\'%b %e, %Y %I:%M:%S %p\', invoice_date) WHEN REGEXP_CONTAINS(invoice_date, r\'^[0-9]{1,2} [a-zA-Z]+ [0-9]{4}$\') THEN DATETIME(PARSE_DATE(\'%d %B %Y\', invoice_date)) ELSE NULL END AS invoice_date, CASE WHEN REGEXP_REPLACE(item_tax, r\'[^0-9.]\', \'\') IN (\'\', \'.\') THEN NULL ELSE CAST(REGEXP_REPLACE(item_tax, r\'[^0-9.]\', \'\') AS FLOAT64) END AS item_tax, CASE WHEN REGEXP_REPLACE(item_price_without_tax, r\'[^0-9.]\', \'\') IN (\'\', \'.\') THEN NULL ELSE CAST(REGEXP_REPLACE(item_price_without_tax, r\'[^0-9.]\', \'\') AS FLOAT64) END AS item_price_without_tax, CASE WHEN REGEXP_REPLACE(Order_Tax_After_Discount, r\'[^0-9.]\', \'\') IN (\'\', \'.\') THEN NULL ELSE CAST(REGEXP_REPLACE(Order_Tax_After_Discount, r\'[^0-9.]\', \'\') AS FLOAT64) END AS Order_Tax_After_Discount, CASE WHEN REGEXP_REPLACE(Order_Grand_Total_After_Discount, r\'[^0-9.]\', \'\') IN (\'\', \'.\') THEN NULL ELSE CAST(REGEXP_REPLACE(Order_Grand_Total_After_Discount, r\'[^0-9.]\', \'\') AS FLOAT64) END AS Order_Grand_Total_After_Discount, CASE WHEN REGEXP_REPLACE(Order_Base_Grand_Total_After_Discount, r\'[^0-9.]\', \'\') IN (\'\', \'.\') THEN NULL ELSE CAST(REGEXP_REPLACE(Order_Base_Grand_Total_After_Discount, r\'[^0-9.]\', \'\') AS FLOAT64) END AS Order_Base_Grand_Total_After_Discount, CASE WHEN REGEXP_REPLACE(Order_Discount, r\'[^0-9.]\', \'\') IN (\'\', \'.\') THEN NULL ELSE CAST(REGEXP_REPLACE(Order_Discount, r\'[^0-9.]\', \'\') AS FLOAT64) END AS Order_Discount, CASE WHEN REGEXP_REPLACE(Order_Shipping, r\'[^0-9.]\', \'\') IN (\'\', \'.\') THEN NULL ELSE CAST(REGEXP_REPLACE(Order_Shipping, r\'[^0-9.]\', \'\') AS FLOAT64) END AS Order_Shipping, CASE WHEN REGEXP_REPLACE(Order_Subtotal, r\'[^0-9.]\', \'\') IN (\'\', \'.\') THEN NULL ELSE CAST(REGEXP_REPLACE(Order_Subtotal, r\'[^0-9.]\', \'\') AS FLOAT64) END AS Order_Subtotal, CASE WHEN REGEXP_REPLACE(Total_Qty_Items_Ordered, r\'[^0-9]\', \'\') = \'\' THEN NULL ELSE CAST(REGEXP_REPLACE(Total_Qty_Items_Ordered, r\'[^0-9]\', \'\') AS INT64) END AS Quantity, CASE WHEN REGEXP_REPLACE(Order_Refunded, r\'[^0-9]\', \'\') = \'\' THEN NULL ELSE CAST(REGEXP_REPLACE(Order_Refunded, r\'[^0-9]\', \'\') AS INT64) END AS Order_Refunded from maplemonk.fablestreet_historical_website_sales ; CREATE OR REPLACE TABLE `fablestreet-wh.Maplemonk.fablestreet_wh_historical_orders_Final_customerID` AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(REPLACE(billing_contact, \' \', \'\'), r\'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, billing_contact as phone FROM `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_intermediate` ) a ), int AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, r\'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT REPLACE(billing_contact, \' \', \'\') AS contact_num, email FROM `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_intermediate` ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, r\'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM int WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(CAST(ORDER_date AS DATE)) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(order_date AS DATE) END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS website_first_complete_order_date, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_intermediate` o LEFT JOIN ( SELECT contact_num AS phone, maple_monk_id FROM ( SELECT contact_num, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM `fablestreet-wh.Maplemonk.fablestreet_wh_historical_orders_Final_customerID` ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.billing_contact, r\'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM `fablestreet-wh.Maplemonk.fablestreet_wh_historical_orders_Final_customerID` WHERE contact_num IS NULL ) d ON d.email = m.email; ALTER TABLE `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_source STRING; UPDATE `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` AS A SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_number, customer_id_final, order_date, CASE WHEN DATE(order_date) =website_first_complete_order_date THEN \'New\' WHEN DATE(order_date) <website_first_complete_order_date OR website_first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN DATE(order_date) >website_first_complete_order_date THEN \'Repeat\' END AS flag FROM `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` ) AS B WHERE A.order_number = B.order_number AND A.customer_id_final = B.customer_id_final AND DATE(A.order_date) = DATE(B.order_date); UPDATE `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' WHEN new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) IN (\'cancelled\') END) THEN \'Yet to make completed order\' ELSE new_customer_flag END where true; UPDATE `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_number, customer_id_final, DATE(order_date) AS Order_Date, CASE WHEN LAST_DAY(DATE(order_date)) = LAST_DAY(DATE(website_first_complete_order_date)) THEN \'New\' WHEN LAST_DAY(DATE(order_date)) < LAST_DAY(DATE(website_first_complete_order_date)) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN LAST_DAY(DATE(order_date)) > LAST_DAY(DATE(website_first_complete_order_date)) THEN \'Repeat\' END AS Flag FROM `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` ) AS B WHERE A.order_number = B.order_number AND A.customer_id_final = B.customer_id_final; UPDATE `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' ELSE new_customer_flag_month END WHERE true; CREATE OR REPLACE TABLE `fablestreet-wh.Maplemonk.website_temp_source_1` AS SELECT customer_id_final, channel, source FROM ( SELECT DISTINCT customer_id_final, DATE(order_date) AS order_Date, SOURCE, SOURCE AS CHANNEL, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN DATE(order_date) END) OVER (PARTITION BY customer_id_final) AS firstOrderdate, row_number() over(partition by customer_id_final order by 1 desc) rw FROM `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` ) res WHERE order_Date = firstOrderdate and rw = 1; UPDATE `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` AS a SET a.acquisition_channel = b.channel FROM `fablestreet-wh.Maplemonk.website_temp_source_1` b WHERE a.customer_id_final = b.customer_id_final; UPDATE `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` AS a SET a.acquisition_source = b.source FROM `fablestreet-wh.Maplemonk.website_temp_source_1` b WHERE a.customer_id_final = b.customer_id_final; CREATE OR REPLACE TABLE `fablestreet-wh.Maplemonk.website_temp_product_1` AS SELECT DISTINCT customer_id_final, product_name_final, ROW_NUMBER() OVER (PARTITION BY customer_id_final ORDER BY total_sales DESC) AS rowid FROM ( SELECT DISTINCT customer_id_final, CAST(order_date AS DATE) AS order_date, upper(product_name) as product_name_final, Order_Grand_Total_After_Discount as total_sales, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(order_date AS DATE) END) OVER (PARTITION BY customer_id_final) AS firstOrderdate FROM `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` ) res WHERE order_date = firstOrderdate; UPDATE fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items AS A SET A.acquisition_product=B.product_name_final FROM ( SELECT * FROM fablestreet-wh.Maplemonk.website_temp_product_1 WHERE rowid=1)B WHERE A.customer_id_final = B.customer_id_final; ALTER TABLE `fablestreet-wh.Maplemonk.fablestreet_historical_website_sales_fact_items` ADD COLUMN SHIPPING_TAX FLOAT64, ADD COLUMN SHIP_PROMOTION_DISCOUNT FLOAT64, ADD COLUMN GIFT_WRAP_PRICE FLOAT64, ADD COLUMN GIFT_WRAP_TAX FLOAT64;",
                    "transaction": true
                }
            ) }}
